/* Lyceum timetable integration. Source: W1RCHER/Visual. */
(function(){
'use strict';
function ready(){
 if(document.getElementById('lyceum-schedule-style'))return;
 const url='/ru/schedule/';
 function link(where,text){const a=document.createElement('a');a.href=url;a.textContent=text||'Расписание занятий';a.dataset.lyceumScheduleLink=where;return a;}
 const css=document.createElement('style');css.id='lyceum-schedule-style';css.textContent=`
.lyceum-schedule-widget{margin:10px 0 16px}.lyceum-schedule-widget a{display:flex;align-items:center;gap:12px;padding:14px 18px;color:#050731;background:#a1ced2;border-radius:5px;text-decoration:none;box-shadow:inset 0 0 10px #d0e9eb;font:18px Arial,sans-serif;min-height:64px}.lyceum-schedule-widget a:hover{background:#b6dce0}.lyceum-schedule-widget span{font-size:28px}.mainMenu>ul>li.lyceum-schedule-row-break{display:block;height:0;overflow:hidden;padding:0;margin:0;border:0}.mainMenu>ul>li.lyceum-schedule-row-break~li>a{font-size:1.45em;padding:10px 10px}#lyceum-schedule-frame{display:block;width:100%;height:800px;border:0;background:transparent}#lyceum-schedule{width:100%;min-width:0}`;
 document.head.append(css);
 const top=document.getElementById('service_menu_top_map');if(top&&!document.querySelector('[data-lyceum-schedule-link="top"]')){const li=document.createElement('li');li.append(link('top','расписание занятий'));top.parentElement.after(li);}
 const access=document.querySelector('.widget_accessibility_column');if(access&&!document.querySelector('[data-lyceum-schedule-link="sidebar"]')){const box=document.createElement('div');box.className='lyceum-schedule-widget';const a=link('sidebar');const icon=document.createElement('span');icon.textContent='▦';icon.setAttribute('aria-hidden','true');a.prepend(icon);box.append(a);access.after(box);}
 const exam=Array.from(document.querySelectorAll('.mainMenu a')).find(a=>a.textContent.trim()==='Экзамены');if(exam&&!Array.from(document.querySelectorAll('.mainMenu a')).some(a=>a.textContent.trim()==='Расписание занятий')){const br=document.createElement('li');br.className='lyceum-schedule-row-break';br.setAttribute('aria-hidden','true');const li=document.createElement('li');li.className='item';li.append(link('menu'));exam.parentElement.before(br,li);}
 const mount=document.getElementById('lyceum-schedule');if(!mount)return;
 async function load(){
  const packed=Uint8Array.from(atob(''),c=>c.charCodeAt(0));
  const stream=new Blob([packed]).stream().pipeThrough(new DecompressionStream('gzip'));
  const html=await new Response(stream).text();
  const frame=document.createElement('iframe');frame.id='lyceum-schedule-frame';frame.title='Интерактивное расписание и карта кабинетов';
  frame.setAttribute('sandbox','allow-scripts');
  window.addEventListener('message',e=>{if(e.source===frame.contentWindow&&e.data&&e.data.type==='lyceum-schedule-height'&&Number.isFinite(e.data.height))frame.style.height=Math.min(15000,Math.max(600,e.data.height))+'px';});
  frame.srcdoc=html;mount.replaceChildren(frame);
 }
 load().catch(error=>{mount.textContent='Не удалось загрузить расписание. Обновите страницу или откройте её в современном браузере.';console.error('Timetable loading failed',error);});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready,{once:true});else ready();
})();
